INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('bf275970-7d49-47d7-8504-824101995b37', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 0, 'Ser nova criação significa ter uma vida transformada por Cristo, deixando para trás os erros do passado e vivendo de uma forma melhor.', '2026-05-14 03:34:53.743797+00', '2026-05-14 03:34:53.743797+00', NULL) ON CONFLICT DO NOTHING;
