INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('e9a162bc-8239-4984-8886-4e9d9d16e24c', 'f753b131-e334-4645-95d6-dd7f3f1193fc', '4923904c-0624-414c-a226-c0e44bf04174', 0, 'Significa que eu tenho um propósito pra vida, que eu não nasci acidentalmente.', '2026-05-18 21:57:34.134131+00', '2026-05-18 21:57:34.134131+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('9c995827-6f81-4847-a2cf-8ba012951e56', 'f753b131-e334-4645-95d6-dd7f3f1193fc', '4923904c-0624-414c-a226-c0e44bf04174', 1, 'Talvez salvar ele de um acidente, não só isso como dar a vida por ele, como Jesus fez por nós.', '2026-05-18 21:57:34.134131+00', '2026-05-18 21:57:34.134131+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('a5d5e97f-b3c6-4926-9eb4-f7ad60887d26', 'f753b131-e334-4645-95d6-dd7f3f1193fc', '4923904c-0624-414c-a226-c0e44bf04174', 2, 'Muda saber que Deus deu seu filho para nós salvar, e isso significa que nós temos uma longa vida pra viver, muitas conquistas para conquistar.', '2026-05-18 21:57:34.134131+00', '2026-05-18 21:57:34.134131+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('3c325eed-75df-483d-9fd0-64439c690c45', 'f753b131-e334-4645-95d6-dd7f3f1193fc', 'e3645858-1004-4f31-8d73-708e1749c4bd', 0, 'Para mostrar do que elas são possíveis, para que elas mostram que são melhores que todos.', '2026-05-19 22:54:56.229271+00', '2026-05-19 22:54:56.229271+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('60274e4b-4121-43e3-bda0-cd014b22e009', 'f753b131-e334-4645-95d6-dd7f3f1193fc', 'e3645858-1004-4f31-8d73-708e1749c4bd', 1, 'Isso significa que o amor de Deus por nós não depende de quem somos ou do nosso valor, e sim mostrando o nosso amor por ele.', '2026-05-19 22:54:56.229271+00', '2026-05-19 22:54:56.229271+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('565bf9a6-dbec-498e-9f35-c7d044273471', 'f753b131-e334-4645-95d6-dd7f3f1193fc', 'e3645858-1004-4f31-8d73-708e1749c4bd', 2, 'Na minha opinião muda saber que Deus nos adora, e não sobre como mostramos nossos valor tentando ser o melhor de todos, e sim mostrando o quanto tem fé nele.', '2026-05-19 22:54:56.229271+00', '2026-05-19 22:54:56.229271+00', NULL) ON CONFLICT DO NOTHING;
