INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('934800a5-e71f-4bdf-8c5a-c9ed23a08bf9', 'c703cab4-4562-496e-9243-fd6bd05d9a80', 'ba0f8dfe-02e3-4c8a-8bfc-16a9ce1afde9', 0, 'Às vezes sinto medo, mas lembro que Deus me aceita pela graça, não pelos meus erros.', '2026-04-08 17:27:15.59439+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
