INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('c7287760-c8b5-4a10-952a-c78042b9f8e1', '2f773751-38c2-45a1-8ee0-f5b856092730', 'ba0f8dfe-02e3-4c8a-8bfc-16a9ce1afde9', 1, 'Saber que não há condenação, me faz viver sem medo de Deus me castigar e livre para tentar viver e acertar e mesmo que eu errar não serei castigado.', '2026-04-08 19:28:54.818785+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
