INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('fb35d559-cb1e-4df7-b829-a582119606f6', 'f753b131-e334-4645-95d6-dd7f3f1193fc', 'ba0f8dfe-02e3-4c8a-8bfc-16a9ce1afde9', 1, 'Traz segurança sabendo que Deus tem um propósito pra mim e um futuro lindo, e sempre passo a ter alívio quando penso que Deus sabe e guarda meu futuro.', '2026-04-08 21:37:06.741818+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
