INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('1f02a2fb-1e84-4833-bfbb-bead44a88e6e', '985bc110-c90a-4762-8b1b-7b081e0c6863', '6c37261b-db87-4224-b42f-546e9d6b8f2f', 0, 'Sim. Se Ele é o caminho, posso confiar nisso.', '2026-04-22 13:40:09.524884+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('0b1eae46-3a55-495d-82b9-6ce31abd4124', '985bc110-c90a-4762-8b1b-7b081e0c6863', '6c37261b-db87-4224-b42f-546e9d6b8f2f', 1, 'Às vezes tento fazer isso. Mas lembro do Senhor, do criador, e procuro voltar a confiar nele como sendo o único caminho.', '2026-04-22 13:40:09.524884+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('05fc0fa9-f839-4cf7-8b00-b5847a3b9dac', '985bc110-c90a-4762-8b1b-7b081e0c6863', '2bc9be13-ca22-4f97-a054-0822e279b99b', 0, 'Às vezes esta ideia de merecer a salvação vem à tona. Então, preciso lembrar do sangue derramado na cruz, de como não sou merecedora, mas como Cristo me ama.', '2026-04-22 13:41:59.736244+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
