INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('ed56f890-eaa9-4f9b-8056-4bc10f8fa5b6', '985bc110-c90a-4762-8b1b-7b081e0c6863', '33212d42-ccc1-4887-891d-80c7a46207eb', 1, 'Sim. Mas preciso fazer isso constantemente', '2026-04-22 13:43:18.375716+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
