INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('e141a169-7298-4fa8-b37b-9a4a5c857304', '32a9f112-1192-4b2a-918f-c2895a76ade3', '7d433010-74aa-4b63-bbca-c1db37c6ab21', 1, 'Pois sempre pecamos', '2026-04-22 15:51:48.617793+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('6d08b67b-80a1-46a3-a076-ab8522fd72f2', 'c703cab4-4562-496e-9243-fd6bd05d9a80', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 0, 'Porque ela faz a gente questionar a verdade e perder a confiança em Deus, abrindo espaço para decisões erradas.', '2026-04-22 16:17:10.470994+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('4e501d7e-822c-4903-acb8-0d8d72cfa493', 'c703cab4-4562-496e-9243-fd6bd05d9a80', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 1, 'Quando passo por dificuldades, não entendo o que está acontecendo ou quando sinto medo e insegurança.', '2026-04-22 16:17:10.470994+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('e2cf3f0a-1f44-46f5-a281-f4a4591c2aae', '528f1076-2f86-4c8f-ae7f-cb0a460e4f49', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 0, 'Porque várias pessoas vão perdendo a fé em Deus até que se perguntam algumas perguntas como, será que Deus existe? Será que foi isso mesmo que ele disse?', '2026-04-22 17:57:05.186939+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('0fb13cab-3383-4cd0-b59c-1aba1e325f33', '528f1076-2f86-4c8f-ae7f-cb0a460e4f49', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 1, 'As vezes é difícil quando está tudo "dando errado" na nossa vida .', '2026-04-22 17:57:05.186939+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('2841e771-c86e-44e7-9da7-2b5cb084c216', '2f773751-38c2-45a1-8ee0-f5b856092730', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 0, 'Porque deixamos de confiar em Deus ', '2026-04-22 18:47:09.622947+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('e44b3673-dc4d-4dd7-a7eb-b420761ccfa1', '2f773751-38c2-45a1-8ee0-f5b856092730', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 1, 'Quando perdemos o controle sobre algo e nos problemas da vida. ', '2026-04-22 18:47:09.622947+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('49de60bf-c404-4751-b677-c38ae3837559', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '2e26fe88-3337-4504-a083-c448326f0210', 0, 'Porque o pecado afeta nossa identidade e faz a gente acreditar que nossos erros nos definem. Muitas vezes a culpa e a lembrança do passado falam mais alto, e esquecemos que, em Cristo, podemos ser restaurados e ter uma nova identidade.', '2026-04-22 18:55:20.432737+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('7e37f96b-e9c1-41cf-9239-f8b325cf2800', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '2e26fe88-3337-4504-a083-c448326f0210', 1, 'Significa que, como está em 2 Coríntios 5:17, eu me torno uma nova criatura. As coisas antigas ficam para trás e começo uma nova vida em Cristo. Não sou mais definido pelos meus pecados, mas pelo que Deus diz sobre mim: perdoado, reconciliado e filho de Deus.', '2026-04-22 18:55:20.432737+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('d473f318-d52a-4eb1-b930-8510efb50c3d', '9289d1ce-a632-4cd7-930e-73023e549ec5', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 0, 'Pois ela pode fazer você parar de confiar em Deus,assim sua fé se desfazendo', '2026-04-22 19:36:15.731558+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
