INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('f84dc81b-8907-4773-96cf-aa4999fa1890', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', 'af440fb5-5112-4e54-bbb3-82812e917370', 0, 'As pessoas tentam esconder suas falhas porque sentem vergonha e insegurança, assim como Adão e Eva depois da queda. Antes eles viviam em liberdade, mas depois surgiu o medo, e isso faz a gente querer se esconder e não mostrar nossos erros.', '2026-04-25 00:31:20.016303+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
