INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('18dc655e-d7a2-4ee9-925b-93adb84de682', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '5e859f9e-3016-4482-96fd-1cae2e76f966', 1, 'O pecado afeta a vida das pessoas trazendo medo, culpa, comparação e orgulho, bagunçando o coração e a vida.', '2026-05-12 22:51:38.723663+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('67282aff-37a3-4c70-ab2f-be8dad43d345', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '5e859f9e-3016-4482-96fd-1cae2e76f966', 2, 'É importante entender que todos pecaram porque assim reconhecemos que precisamos de Deus e da salvação em Jesus.', '2026-05-12 22:51:38.723663+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('09087b10-4d64-4c62-8fed-c33ecf9fdcf8', 'f753b131-e334-4645-95d6-dd7f3f1193fc', '5e859f9e-3016-4482-96fd-1cae2e76f966', 0, 'Agente tentar fazer algo que sabe que não consegue para se exibir para os outros, pegar e fazer aquilo mais não assumir que fez.', '2026-05-12 23:02:17.611215+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('cb253b14-1365-4380-a149-c171975f7698', 'f753b131-e334-4645-95d6-dd7f3f1193fc', '5e859f9e-3016-4482-96fd-1cae2e76f966', 1, 'Fazendo com que as pessoas se tornam pecadores, e isso acaba afastando-se de Deus.', '2026-05-12 23:02:17.611215+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
INSERT INTO public.devotional_responses (id, user_id, devotional_id, question_index, response, created_at, updated_at, church_id) VALUES ('4e3ecfef-3615-4a7c-ba1f-01ab5b22eabc', 'f753b131-e334-4645-95d6-dd7f3f1193fc', '5e859f9e-3016-4482-96fd-1cae2e76f966', 2, 'Porque se agente não intender, e achar isso certo, não vai para o céu e Deus não nos perdoa.', '2026-05-12 23:02:17.611215+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
