INSERT INTO public.lesson_responses (id, user_id, lesson_id, question_key, response, created_at, updated_at, church_id) VALUES ('c6a02ad4-07b2-4c7a-a750-f7fbef31a69d', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '3a71d37e-b366-41ca-b6ae-c8fc7f77b522', 'practice', 'Essa semana eu vou escrever verdades sobre quem eu sou em Cristo e ler todos os dias. Quero lembrar que sou amado, perdoado e nova criação, e não deixar que a opinião dos outros defina quem eu sou', '2026-05-02 02:23:21.059573+00', '2026-05-13 12:53:51.627337+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
INSERT INTO public.lesson_responses (id, user_id, lesson_id, question_key, response, created_at, updated_at, church_id) VALUES ('3a003086-0ba3-4940-b50b-c2a5e3adf589', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '3a71d37e-b366-41ca-b6ae-c8fc7f77b522', 'prayer', 'Senhor Deus, Obrigado porque o Senhor nos criou, nos ama e não nos abandonou mesmo quando o pecado entrou no mundo. Obrigado porque Jesus veio para nos salvar, nos perdoar e nos dar uma nova identidade. Ajuda-nos a lembrar que não somos definidos pelo que os outros pensam, pelo que sentimos ou pelos nossos erros, mas pelo teu amor e pela tua graça. Ensina-nos a viver como teus filhos, confiando em quem somos em Cristo. Acompanha-nos nesta semana e fortalece nossa fé. Em nome de Jesus, Amém.
