INSERT INTO public.lesson_responses (id, user_id, lesson_id, question_key, response, created_at, updated_at, church_id) VALUES ('dcea1c7a-6f8b-4610-88a4-78bf6d5fdaf8', '528f1076-2f86-4c8f-ae7f-cb0a460e4f49', '3a71d37e-b366-41ca-b6ae-c8fc7f77b522', 'prayer', 'Senhor Deus obrigada por mais um dia maravilhoso, por essa semana abençoada e por mais um dia de vida, nos proteja de todo o mal, e que eu consiga realizar meu sonhos ! Mas que seja feita a tua vontade, amo você. Amém!', '2026-05-11 20:50:57.521941+00', '2026-05-13 12:53:51.627337+00', '02f08580-80e5-4f57-8a2e-1b078d337278') ON CONFLICT DO NOTHING;
